// Singapore as a grid of dots, for the muted map behind Home. Generated once from the 1 km land outlines in the
// geo-maps project (built from OpenStreetMap data, © OpenStreetMap contributors, ODbL): a dot every 5 units on a
// diagonal grid, kept if it falls inside a coastline (reservoirs are filled in, so the island reads as one shape).
// Map units: 1 unit is 0.001 degree (about 111 m). x grows east from 103.4°E, y grows south from 1.52°N, so the
// map is 900 by 400 units. Each dot is "M x y h0": draw the path with a round line cap to get dots.

export const MAP_WIDTH = 900
export const MAP_HEIGHT = 400

// The space between dots, in map units. Draw them about 0.42 of this wide.
export const DOT_STEP = 5

// A place on the map, in map units.
export const project = (lat, lng) => ({ x: (lng - 103.4) * 1000, y: (1.52 - lat) * 1000 })

